package io.knowledgebrain.gateway;
import java.util.*;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class GradeRetractionProxyTest {
 String id="01a10000-0000-7000-8000-000000000000",base="/api/groups/"+id+"/studies/"+id+"/assignments/"+id+"/submissions/"+id+"/grade/revisions/1/retraction";
 @Test void gradeWriteForwardsIndependentCasAndCookieWithoutCallerActor()throws Exception{var f=new GroupProxyTest();f.init();var r=f.request("PUT",base);r.addHeader("If-Match","\"gr0\"");r.addHeader("Authorization","Bearer spoof");r.addHeader("X-Principal-Id",id);r.setContentType("application/json");r.setContent("{\"state\":\"RETRACTED\",\"reason\":\"Reason\"}".getBytes());f.proxy.proxy(r);verify(f.transport).send(eq(new GatewayRoute("collaboration",base)),eq("PUT"),argThat(h->h.entrySet().stream().filter(e->e.getKey().equalsIgnoreCase("If-Match")).findFirst().orElseThrow().getValue().getFirst().equals("\"gr0\"")&&!h.containsKey("Authorization")&&!h.containsKey("X-Principal-Id")),eq(r.getContentAsByteArray()));}
 @Test void boundedHistoryQueriesAndNoActorSelectors()throws Exception{var f=new GroupProxyTest();f.init();var r=f.request("GET",base+"/revisions");r.setQueryString("before=9223372036854775807&limit=10");f.proxy.proxy(r);verify(f.transport).send(eq(new GatewayRoute("collaboration",base+"/revisions?before=9223372036854775807&limit=10")),eq("GET"),any(),any());for(var query:List.of("authorId="+id,"limit=11","before=0","before=01","before=9223372036854775808","limit=1&limit=2")){var bad=f.request("GET",base+"/revisions");bad.setQueryString(query);assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(bad));}var body=f.request("GET",base);body.setContent("{}".getBytes());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->f.proxy.proxy(body));}
}
